INSERT INTO privado.nay_nota_conversa (fone8, linha, dia, nota, resumo, erros) VALUES
  ('81100198', 'captacao', DATE '2026-11-05', 45, 'Lead Chaves na Mão (3883): abertura certa, mas 3 min depois disse que o dono decidiu não vender, o que é falso (cadastro Disponível, dono confirmou venda em 13/10)', '["Inventou que ''o proprietário decidiu não vender'' o 3883, desmentindo a própria oferta de 3 min antes; imovel Disponível e o dono disse ''Disponível'' e o valor em 13/10", "Pergunta ''Ela está documentada?'' ficou para ''confirmar com a equipe'', mas o dono já tinha dito em 13/10: só documentação da construtora, habite-se e IPTU, sem registro; e até 09:54 nenhuma dúvida foi ", "Abertura em texto e card logo em seguida repetem os mesmos dados; o card diz ''mobiliado'' e o cadastro diz ''com modulados e ar''"]'::jsonb),
  ('81819145', 'captacao', DATE '2026-11-05', 75, 'Imóvel 9109 serve ao pedido (locação, Ponta Negra Village, até 7 mil, modulados) e a visita anda, mas o card foi reenviado como ''opção nova'' (já saiu em 02/11)', '["Mandou o 9109 como ''Apareceu uma opção nova'', mas o mesmo card já tinha saído duas vezes em 02/11 (15:14 e 15:17); o ''Posso visitar agora?'' dela de 02/11 nunca teve resposta", "Chama de ''Sr. Karis'' uma cliente (Karis Tarita, que escreveu ''Obrigada'')", "Frase estranha: ''A casa do Ponta Negra Village combina com o que o senhor procura.'' devolvendo o ''Sim'' dela como afirmação"]'::jsonb),
  ('91162924', 'captacao', DATE '2026-11-05', 70, 'Corretor parceiro cobrou o retorno da proposta do Maison Rochelle; a Nay repetiu a mesma promessa de 02/11 sem nunca ter voltado nem passado à equipe', '["Prometeu em 02/11 ''vou confirmar com o cliente sobre a proposta e te retorno'' e não voltou em 3 dias; não há dúvida/aviso aberto para a equipe sobre essa proposta", "Hoje repetiu a mesma frase quase igual à de 02/11, de novo sem prazo nem encaminhamento"]'::jsonb),
  ('91557651', 'parceria', DATE '2026-11-05', 10, '1125: não entendeu ''só se o dono puser camas e geladeira'', disse ''todo mobiliado'' contra o que o dono informou e reenviou fotos que ela já tinha', '["Não entendeu a resposta sobre o 1125 (o dono pôr camas e geladeira), perguntou o teto e reofereceu o próprio 1125 como ''Encontrei este''", "Informação errada: ''é alugado todo mobiliado; o proprietário raramente tira os móveis'' e ''Sim, é mobiliado'', quando o dono informou ontem só armários, ar e guarda-roupas, sem geladeira", "''É este imóvel?'' e reenvio de card + 10 fotos sem pedido; ela reclamou ''já me passou várias vezes''", "Respondeu ''O apto está semi mobiliado'' com ''já te mandei às 09h19, quer de novo?''", "''As fotos que foram no grupo são todas'' não respondia o que ela disse"]'::jsonb),
  ('92419640', 'parceria', DATE '2026-11-05', 25, 'Pediu Parque 10/Dom Pedro/Vieiralves, 2q, até 2.700: perdeu o Parque 10, mandou casa 3q 2.900; o 9060 (Parque 10, 2.700) só veio depois, como ''mais longe''', '["O 2º áudio trocou a região (Dom Pedro, Parque 10, N.S. Graças) só por N.S. Graças: o 9060 Verdes Mares I (Parque 10, 2q, R$ 2.700) não saiu às 08:17 e depois veio como ''um pouco mais longe''", "''De qual imóvel você fala?'' quando ela já tinha dito Iça Paraíba (depois ''Qual deles?'' na lista colada)", "''Está perguntando para outro cliente, certo?'' sem motivo (era a mesma cliente)", "''Sim, sou corretora, é minha cliente'' virou ''Combinado, fico no aguardo'' e ela respondeu ''não entendi, fica no aguardo de quê?''", "''É este imóvel?'' desnecessário antes das fotos do 5709 (era a única opção)"]'::jsonb),
  ('92485907', 'parceria', DATE '2026-11-05', 45, '''Casa em Flores até 850 mil'' foi buscada como locação no Passaredo (filtro de 02/11): disse que não tinha, mas há 5613 (650 mil) e 2120 (480 mil) à venda', '["Disse ''não tenho nenhuma casa nesse perfil'' em Flores até R$ 850 mil: buscou locação com o condomínio Passaredo do pedido de 02/11, e há as casas 5613 e 2120 à venda em Flores", "Bairro Ajuricaba lido como ''Condomínio Flat Edifício Ajuricaba'' (Centro): ''não tenho para locação''", "Ordem trocada: ''Qual região?'' saiu antes da resposta sobre a casa em Flores"]'::jsonb),
  ('81275642', 'parceria', DATE '2026-11-05', 60, 'Perguntou casa ou apto duas vezes num pedido claro de apartamento e a locação até 2.800 ficou sem resposta; a compra no Pq Mosaico saiu certa (5741)', '["''Casa ou apartamento?'' com o pedido de andar alto/elevador nos condomínios Vitali, Parque Ville e Smart Flores, e repetido (''Só para continuarmos... casa ou apartamento?'')", "Pedido de locação até R$ 2.800 perto do Clube Municipal nunca foi buscado (a conversa passou para a compra)", "''No Vista dos Jatobás não tenho'' quando ele só contou que já tinha mostrado um Jatobás"]'::jsonb),
  ('82457847', 'parceria', DATE '2026-11-05', 65, 'River Park à venda: o ''não tenho'' estava certo (só há de parceiro), mas mandou Adrianópolis e Centro de 620 a 800 mil como ''região que você pediu''', '["Manteve a região e o teto do pedido antigo (Adrianópolis/Aleixo, até R$ 750 mil) e ofereceu 4020, 3841, 4497 e 5606, longe do River Park (Colônia Terra Nova) e fora do perfil"]'::jsonb),
  ('81537160', 'parceria', DATE '2026-11-05', 75, 'Busca na Glória/Santo Antônio/Alvorada correta e terminou com info e fotos do 5699, mas perguntou ''Qual deles?'' com só um no Parque 10', '["''Me manda esse do Parque da 10'' respondido com ''Qual deles?'' e a lista de 5 (só o 5699 é do Parque 10)", "''Essa eu vou precisar confirmar'' sobre o financiamento, que está na ficha (a correção do agente respondeu 1,5 min depois)", "2ª mensagem do follow-up (''o que está procurando?'') saiu 4 s depois de ele já ter dito o que procurava"]'::jsonb),
  ('91081525', 'parceria', DATE '2026-11-05', 85, 'Recado bem tratado; ''Mosaico'' não foi reconhecido e a busca usou a região do pedido anterior, dita como ''região que você pediu''; ofereceu o 5722 (2.100)', '["''Mosaico'' ignorado: buscou em Tancredo Neves/Parque 10 (pedido anterior) e chamou de ''região que você pediu''"]'::jsonb),
  ('82508525', 'parceria', DATE '2026-11-05', 85, 'Respondeu ''Precisa ser térreo'' com ''em qual bairro?'' logo depois do follow-up perguntar o mesmo; não comentou que o 5733 é 1º andar', '["Duas perguntas quase iguais em 9 s (follow-up ''o que está procurando?'' e ''em qual bairro?'')", "Ignorou o ''precisa ser térreo'' (o 5733 do follow-up tem 1 lance de escada)"]'::jsonb),
  ('92368763', 'parceria', DATE '2026-11-05', 95, 'Visita do 5725: aguardo e follow-up certos; a correção da madrugada saiu às 06:00 dizendo ''resposta dela amanhã'' quando já era o dia combinado', '["Correção do agente enviada às 06:00 de 05/11 falando ''amanhã'' (a resposta era para hoje)"]'::jsonb),
  ('91683202', 'parceria', DATE '2026-11-05', 100, 'Follow-up; ''ainda não, tô anunciando'' respondido com ''Combinado, fico no aguardo.'' uma vez. Certo.', '[]'::jsonb),
  ('93913589', 'parceria', DATE '2026-11-05', 100, 'Follow-up; ''Obrigada'' ficou sem resposta, como manda a regra do agradecimento.', '[]'::jsonb),
  ('82821650', 'parceria', DATE '2026-11-05', 100, 'Follow-up; corretor disse que o cliente não quis e que já passou o catálogo. Silêncio adequado (Tel tinha assumido em 03/11).', '[]'::jsonb)
